'use client';

// Vendored from MerchFlow Charts components/web/ReportChrome.tsx (commit in lib/merch-flow-report/VENDORED.md).
// Generated by scripts/sync-merch-flow-report.mjs; edit the PATCHES there, not this file.

import { LinkButton, CopyButton } from '@/components/merch-flow-report/ui';

/**
 * Chrome around a shared report: a sticky header with section tabs, and on
 * phone a fixed bottom bar so Download PDF and Copy link stay in reach
 * without scrolling back up.
 */

const SECTIONS = [
  { id: 'summary', label: 'Summary' },
  { id: 'shows', label: 'Shows' },
  { id: 'products', label: 'Products' },
  { id: 'mix', label: 'Mix' },
  { id: 'all-products', label: 'All products' },
] as const;

export function ReportHeader({
  artist,
  tourName,
  pdfHref,
  pdfLabel = 'Download PDF',
}: {
  artist: string;
  tourName: string;
  pdfHref: string;
  pdfLabel?: string;
}) {
  return (
    <div className="sticky top-0 z-20 border-b border-[#E5E7EB] bg-white/95 backdrop-blur">
      <div className="mx-auto w-full max-w-6xl px-4 sm:px-8">
        <div className="flex items-center gap-4 py-3">
          {/* eslint-disable-next-line @next/next/no-img-element */}
          <img
            src="/gms-logo.png"
            alt="Global Merchandising Services"
            className="h-5 w-auto shrink-0"
          />
          <div className="h-6 w-px shrink-0 bg-[#E5E7EB]" aria-hidden="true" />
          <div className="min-w-0 flex-1">
            <p className="truncate text-[15px] font-bold text-ink">{artist}</p>
            <p className="truncate text-[13px] text-[#374151]">{tourName}</p>
          </div>

          <div className="hidden shrink-0 items-center gap-2 sm:flex">
            <CopyButton
              value={typeof window === 'undefined' ? '' : window.location.href}
              label="Copy link"
            />
            <LinkButton href={pdfHref} size="sm">
              {pdfLabel}
            </LinkButton>
          </div>
        </div>

        {/* Tabs scroll horizontally on phone rather than wrapping. */}
        <nav aria-label="Report sections" className="-mx-4 overflow-x-auto px-4 sm:-mx-3 sm:px-0">
          <ul className="flex gap-1 pb-2">
            {SECTIONS.map((section) => (
              <li key={section.id}>
                <a
                  href={`#${section.id}`}
                  className="inline-flex h-9 items-center whitespace-nowrap rounded-full px-3 text-[14px] font-semibold text-[#374151] transition-colors hover:bg-[#F1F2F4] hover:text-ink"
                >
                  {section.label}
                </a>
              </li>
            ))}
          </ul>
        </nav>
      </div>
    </div>
  );
}

export function ReportBottomBar({
  pdfHref,
  pdfLabel = 'Download PDF',
}: {
  pdfHref: string;
  pdfLabel?: string;
}) {
  return (
    <div className="sticky bottom-0 z-20 border-t border-[#E5E7EB] bg-white/95 px-4 py-2.5 backdrop-blur sm:hidden">
      <div className="flex gap-2">
        <CopyButton
          value={typeof window === 'undefined' ? '' : window.location.href}
          label="Copy link"
          size="md"
        />
        <LinkButton href={pdfHref} className="flex-1">
          {pdfLabel}
        </LinkButton>
      </div>
    </div>
  );
}
